      "content": "{\n  \"diagnostics\": [\n    \"PULSE_REPORT_INPUT_INVALID\",\n    \"PULSE_REPORT_EVIDENCE_MISSING\",\n    \"PULSE_REPORT_STALE\",\n    \"PULSE_REPORT_INCOMPATIBLE\",\n    \"PULSE_REPORT_OUTPUT_UNSAFE\",\n    \"PULSE_REPORT_OUTPUT_FAILED\"\n  ],\n  \"examples\": [\n    \"pulse report ./my-pulse-app\",\n    \"pulse report --artifact ./dist/pulse-compile.json --json\"\n  ],\n  \"exit\": \"0 for an eligible report even when optional evidence is unavailable; 2 for usage or unsafe output; 3 for invalid, missing, stale or incompatible evidence or an output write failure.\",\n  \"globalOptions\": [\n    {\n      \"description\": \"Print public CLI help and exit.\",\n      \"flags\": [\n        {\n          \"name\": \"--help\"\n        },\n        {\n          \"name\": \"-h\"\n        }\n      ],\n      \"id\": \"help\",\n      \"key\": \"help\",\n      \"kind\": \"boolean\"\n    },\n    {\n      \"description\": \"Emit machine-readable JSON. pulse dev emits one JSON event per line.\",\n      \"flags\": [\n        {\n          \"name\": \"--json\"\n        }\n      ],\n      \"id\": \"json\",\n      \"key\": \"json\",\n      \"kind\": \"boolean\"\n    },\n    {\n      \"description\": \"Resolve and report the command plan without executing it.\",\n      \"flags\": [\n        {\n          \"name\": \"--dry-run\"\n        },\n        {\n          \"name\": \"--plan\"\n        }\n      ],\n      \"id\": \"dry-run\",\n      \"key\": \"dryRun\",\n      \"kind\": \"boolean\"\n    }\n  ],\n  \"name\": \"report\",\n  \"options\": [\n    {\n      \"description\": \"Write a self-contained offline HTML report; mutually exclusive with --json.\",\n      \"flags\": [\n        {\n          \"name\": \"--html\"\n        }\n      ],\n      \"id\": \"html\",\n      \"key\": \"html\",\n      \"kind\": \"boolean\"\n    },\n    {\n      \"description\": \"Select a project profile. Precedence: --profile, PULSE_PROFILE, pulse.defaultProfile.\",\n      \"flags\": [\n        {\n          \"name\": \"--profile\"\n        }\n      ],\n      \"id\": \"profile\",\n      \"key\": \"profile\",\n      \"kind\": \"value\",\n      \"valueName\": \"<profile>\"\n    },\n    {\n      \"description\": \"HTML destination under the selected root; requires --html. Defaults to .pulse/reports/pulse-report.html.\",\n      \"flags\": [\n        {\n          \"name\": \"--out\"\n        }\n      ],\n      \"id\": \"out\",\n      \"key\": \"outDir\",\n      \"kind\": \"value\",\n      \"valueName\": \"<file.html>\"\n    },\n    {\n      \"description\": \"Replay a saved Report capsule or supported completed-Wasm manifest without loading project code.\",\n      \"flags\": [\n        {\n          \"name\": \"--artifact\"\n        }\n      ],\n      \"id\": \"artifact\",\n      \"key\": \"artifact\",\n      \"kind\": \"value\",\n      \"valueName\": \"<file.json>\"\n    }\n  ],\n  \"outputs\": [\n    \"Default output is a bounded terminal overview; --json emits one complete authoritative Report capsule.\",\n    \"Historical capsule replay preserves evidence identity without claiming current-project freshness.\",\n    \"--html writes an offline route-first viewer with expandable schemas and full-capsule JSON export; it does not open a browser.\"\n  ],\n  \"positionals\": [\n    {\n      \"description\": \"Project discovery start. Defaults to the current directory.\",\n      \"key\": \"directory\",\n      \"name\": \"directory\"\n    }\n  ],\n  \"sideEffects\": [\n    \"Reads retained local evidence only; does not build, run tests, load project code, access secrets or contact the network.\",\n    \"--plan and --dry-run describe intent without collecting or writing a report.\",\n    \"--out requires --html; destinations must be contained regular .html files. Artifact roots are the input JSON parent directory.\",\n    \"HTML writes a bounded .pulse-report-outputs receipt beside its destination; only matching generated bytes are excluded from project input scans. Recorded build inputs cannot be overwritten.\",\n    \"Reports are build-review artifacts; review contents before sharing publicly.\"\n  ],\n  \"summary\": \"Review retained evidence from a completed Native build without rebuilding or executing project code.\",\n  \"usage\": [\n    \"pulse report [directory] [--profile <name>] [--json | --html] [--out <file.html>]\",\n    \"pulse report --artifact <file.json> [--json | --html] [--out <file.html>]\"\n  ]\n}",
